INSERT INTO providers (id, slug, name, type, area, address, tagline, about, hours_text, amenities_json, art, status, live_since) VALUES
('p1', 'lumiere-skin-and-laser-clinic', 'Lumière Skin & Laser Clinic', 'Clinic', 'Kowdiar', 'TC 9/1420, Kowdiar Gardens Road, Kowdiar, Thiruvananthapuram 695003', 'Consultant-led dermatology and aesthetic skin care', 'A calm, consultant-led skin clinic near Kowdiar Square. Every medical treatment starts with an in-person assessment by a registered dermatologist, who will discuss whether a treatment is appropriate for you, the alternatives, and realistic expectations. Non-medical facials are delivered by certified aesthetic therapists.', 'Mon–Sat · 10:00–19:00', '["Private consultation rooms","Female practitioners available","Parking","Card & UPI"]', 0, 'live', '2026-08-03'),
('p2', 'saanvi-ayur-wellness', 'Saanvi Ayur Wellness', 'Wellness centre', 'Vellayambalam', 'Saanvi House, Sasthamangalam Road, Vellayambalam, Thiruvananthapuram 695010', 'Traditional Kerala Ayurveda therapies in a heritage tharavad setting', 'Classical Kerala therapies — abhyanga, shirodhara and kizhi — in a restored tharavad home. Therapies are wellness services; an optional consultation with our BAMS physician is available and recommended before any therapeutic programme.', 'Daily · 08:00–20:00', '["Heritage setting","Shower & changing rooms","Herbal tea lounge","UPI"]', 1, 'live', '2026-08-03'),
('p3', 'ivory-room-beauty-studio', 'Ivory Room Beauty Studio', 'Salon & studio', 'Pattom', '2nd Floor, Plamoodu Junction, Pattom, Thiruvananthapuram 695004', 'Editorial hair, bridal makeup and facials', 'A light-filled studio above Pattom junction for considered cuts, colour, bridal trials and skin-loving facials. Non-medical beauty services only.', 'Tue–Sun · 10:00–20:00', '["Bridal suite","Women-only floor","Complimentary coffee","Card & UPI"]', 2, 'live', '2026-09-07'),
('p4', 'dr-kavya-raghunath', 'Dr. Kavya Raghunath', 'Independent practitioner', 'Kazhakkoottam', 'Consulting suite 4, Technopark Phase I Road, Kazhakkoottam, Thiruvananthapuram 695582', 'Consultant dermatologist & trichologist', 'Independent consultant specialising in hair and scalp conditions, consulting from a shared clinical suite near Technopark. Procedures such as PRP are only offered after a full assessment and are not suitable for everyone.', 'Mon–Fri · 12:00–20:00 · Sat 10:00–14:00', '["Evening slots for Technopark staff","Online follow-ups","UPI"]', 3, 'live', '2026-08-03'),
('p5', 'kaya-mudra-physio-and-pilates', 'Kaya Mudra Physio & Pilates', 'Wellness centre', 'Kazhakkoottam', 'Near Infosys Gate, Kazhakkoottam Bypass, Thiruvananthapuram 695582', 'Physiotherapy, reformer Pilates and recovery', 'Evidence-led physiotherapy assessments and small-room reformer Pilates. Clinical assessments are delivered by registered physiotherapists; Pilates and sports massage are non-medical fitness services.', 'Mon–Sat · 07:00–21:00', '["Reformer studio","Showers","Parking","Card & UPI"]', 5, 'live', '2026-08-24'),
('p6', 'thalam-nail-and-brow-bar', 'Thalam Nail & Brow Bar', 'Salon & studio', 'Kowdiar', 'Ground Floor, Golf Links Road, Kowdiar, Thiruvananthapuram 695003', 'Gel nails, lash lifts and brow artistry', 'A small, meticulous studio for long-wear gel, hand-painted nail art, lash lifts and laminated brows. Single-use files and autoclaved tools.', 'Daily · 11:00–20:00', '["Hygiene-first tools","Women-only","UPI"]', 4, 'live', '2026-09-14'),
('p7', 'veda-smile-studio', 'Veda Smile Studio', 'Clinic', 'Vellayambalam', 'Opp. Museum Road, Vellayambalam, Thiruvananthapuram 695010', 'Aesthetic dentistry & smile consultations', 'A boutique dental practice focusing on smile assessments, professional whitening and preventive care. Whitening is offered only after a dental examination confirms it is appropriate.', 'Mon–Sat · 10:00–20:00', '["Digital smile preview","Evening appointments","Card & UPI"]', 6, 'live', '2026-08-10'),
('p8', 'ember-and-oud-grooming', 'Ember & Oud Grooming', 'Salon & studio', 'Pattom', 'Kesavadasapuram–Pattom Road, Pattom, Thiruvananthapuram 695004', 'Modern grooming lounge — cuts, beard and skin', 'Precise cuts, beard sculpting and de-tan facials in an unhurried lounge. Non-medical grooming services.', 'Daily · 10:00–21:00', '["Walk-in friendly","Card & UPI"]', 7, 'live', '2026-10-06');
