INSERT INTO staff (id, provider_id, name, role, medical, quals_json, registration, years, langs_json, bio) VALUES
('s1', 'p1', 'Dr. Meera Nair', 'Consultant Dermatologist', 1, '["MBBS — Govt. Medical College, Thiruvananthapuram","MD Dermatology, Venereology & Leprosy","Fellowship in Aesthetic Dermatology"]', 'TCMC Reg. No. 48XXX (sample)', 14, '["Malayalam","English","Hindi"]', 'Focuses on acne, pigmentation and conservative aesthetic care. Prefers stepwise plans and will tell you when a treatment isn’t right for you.'),
('s2', 'p1', 'Dr. Arjun Menon', 'Dermatologist', 1, '["MBBS","DDVL","Certificate in Laser Dermatology"]', 'TCMC Reg. No. 61XXX (sample)', 8, '["Malayalam","English","Tamil"]', 'Leads the laser and hair-reduction service, including patch testing and skin-type assessment.'),
('s3', 'p1', 'Riya Thomas', 'Aesthetic Therapist', 0, '["CIDESCO Diploma in Beauty Therapy","Advanced facial techniques certificate"]', '', 6, '["Malayalam","English"]', 'Delivers non-medical facials and skin-care routines under the clinic’s protocols.'),
('s4', 'p2', 'Dr. Lakshmi Varma', 'Ayurveda Physician', 1, '["BAMS — Govt. Ayurveda College, Thiruvananthapuram","PG Diploma in Panchakarma"]', 'TCMC (ISM) Reg. No. 12XXX (sample)', 11, '["Malayalam","English"]', 'Offers consultations before therapeutic programmes and advises on whether therapies are suitable alongside other care.'),
('s5', 'p2', 'Anil Kumar', 'Senior Ayurveda Therapist', 0, '["Certificate in Panchakarma Therapy","Kalari marma training"]', '', 15, '["Malayalam"]', 'Specialist in abhyanga and kizhi with a calm, steady technique.'),
('s6', 'p2', 'Devika S', 'Ayurveda Therapist', 0, '["Certificate in Panchakarma Therapy"]', '', 5, '["Malayalam","English"]', 'Female therapist for women-only therapy bookings.'),
('s7', 'p3', 'Neha Pillai', 'Creative Director & Senior Stylist', 0, '["Diploma in Hairdressing","Advanced colour certification"]', '', 12, '["Malayalam","English","Hindi"]', 'Known for soft, lived-in colour and precision bobs.'),
('s8', 'p3', 'Sara Joseph', 'Bridal Makeup Artist', 0, '["Professional Makeup Artistry Diploma"]', '', 9, '["Malayalam","English"]', 'Kerala Christian and Hindu bridal looks — natural, long-wearing, camera-ready.'),
('s9', 'p3', 'Fathima R', 'Skin & Brow Specialist', 0, '["Diploma in Cosmetology (non-medical)"]', '', 4, '["Malayalam","English","Arabic"]', 'Facials, threading and brow shaping.'),
('s10', 'p4', 'Dr. Kavya Raghunath', 'Consultant Dermatologist & Trichologist', 1, '["MBBS","MD Dermatology, Venereology & Leprosy","Fellowship in Trichology"]', 'TCMC Reg. No. 55XXX (sample)', 10, '["Malayalam","English","Kannada"]', 'Hair and scalp specialist. Investigates causes first; procedures are offered only where appropriate.'),
('s11', 'p5', 'Dr. Joel Mathew', 'Physiotherapist', 1, '["BPT","MPT (Musculoskeletal)","Certified Pilates for Rehab"]', 'KSPC Reg. (sample)', 9, '["Malayalam","English"]', 'Back, neck and post-natal rehabilitation. Clear plans with home exercise.'),
('s12', 'p5', 'Ann Maria George', 'Pilates Instructor', 0, '["Comprehensive Reformer Pilates Certification","Sports massage certificate"]', '', 5, '["Malayalam","English"]', 'Reformer sessions for all levels and post-desk recovery.'),
('s13', 'p6', 'Meenu K', 'Lead Nail Artist', 0, '["International nail technician certificate"]', '', 7, '["Malayalam","English"]', 'Hand-painted art and structured gel.'),
('s14', 'p6', 'Ishita Rao', 'Lash & Brow Artist', 0, '["Lash lift & brow lamination certificates"]', '', 4, '["English","Hindi","Malayalam"]', 'Soft, natural lifts and laminated brows.'),
('s15', 'p7', 'Dr. Hari Krishnan', 'Prosthodontist', 1, '["BDS","MDS Prosthodontics","Certificate in Aesthetic Dentistry"]', 'KSDC Reg. (sample)', 13, '["Malayalam","English","Tamil"]', 'Conservative, examination-first approach to smile aesthetics.'),
('s16', 'p8', 'Rahul Das', 'Senior Barber', 0, '["Barbering certificate"]', '', 8, '["Malayalam","English"]', 'Fades, textured crops and beard sculpting.'),
('s17', 'p8', 'Faizal M', 'Grooming Specialist', 0, '["Skin care for men certificate"]', '', 5, '["Malayalam","Hindi"]', 'De-tan facials and head massage.');
