INSERT INTO services (id, provider_id, name, cat, kind, dur_min, price_paise, deposit_paise, description, sort) VALUES
('v1', 'p1', 'Dermatology consultation', 'skin', 'consult', 30, 80000, 30000, 'Assessment of your skin concern with a consultant dermatologist. Includes a written plan; no treatment is assumed.', 0),
('v2', 'p1', 'Acne & scar assessment', 'skin', 'consult', 45, 120000, 40000, 'Detailed assessment of active acne and scarring with options explained, including non-procedural care.', 1),
('v3', 'p1', 'Chemical peel (after assessment)', 'medaes', 'treatment', 45, 350000, 80000, 'Superficial peel for clients already assessed by a clinic doctor. Your practitioner confirms suitability on the day.', 2),
('v4', 'p1', 'Laser hair reduction — consult & patch test', 'medaes', 'consult', 30, 100000, 30000, 'Skin-type assessment and patch test. Treatment sessions are only booked if appropriate.', 3),
('v5', 'p1', 'Hydrating deep-cleanse facial', 'skin', 'beauty', 60, 420000, 80000, 'Non-medical facial: cleanse, gentle exfoliation, extraction and hydration.', 4),
('v6', 'p1', 'Anti-wrinkle injectables consultation', 'medaes', 'consult', 30, 150000, 50000, 'Doctor-led discussion of options, risks and alternatives. Any treatment is decided after assessment, never at booking.', 5),
('v7', 'p2', 'Abhyanga full-body oil massage', 'ayur', 'beauty', 90, 280000, 50000, 'Traditional warm-oil massage followed by steam.', 6),
('v8', 'p2', 'Shirodhara', 'ayur', 'beauty', 60, 240000, 50000, 'A continuous stream of warm oil over the forehead. Wellness service.', 7),
('v9', 'p2', 'Elakizhi herbal pouch therapy', 'ayur', 'beauty', 75, 320000, 60000, 'Warm herbal pouches with medicated oil.', 8),
('v10', 'p2', 'Ayurveda physician consultation', 'ayur', 'consult', 30, 60000, 20000, 'Consultation with a BAMS physician before starting a therapy programme.', 9),
('v11', 'p3', 'Signature cut & blow-dry', 'hair', 'beauty', 60, 140000, 30000, 'Consultation, wash, precision cut and finish.', 10),
('v12', 'p3', 'Keratin smoothing', 'hair', 'beauty', 180, 750000, 150000, 'Frizz-taming smoothing treatment; strand test on the day.', 11),
('v13', 'p3', 'Bridal makeup trial', 'groom', 'beauty', 120, 600000, 150000, 'Full trial of your wedding-day look with photos.', 12),
('v14', 'p3', 'Gold radiance facial', 'skin', 'beauty', 75, 220000, 40000, 'Non-medical brightening facial.', 13),
('v15', 'p3', 'Threading & brow shaping', 'nails', 'beauty', 20, 25000, 0, 'Brow, upper lip or full face threading.', 14),
('v16', 'p4', 'Hair loss consultation', 'hair', 'consult', 40, 100000, 40000, 'History, scalp examination and trichoscopy. Tests may be advised.', 15),
('v17', 'p4', 'PRP scalp session (after assessment)', 'medaes', 'treatment', 60, 650000, 150000, 'Only for existing patients for whom PRP has been recommended after assessment.', 16),
('v18', 'p4', 'Skin follow-up consultation', 'skin', 'consult', 20, 70000, 20000, 'Review of an existing plan.', 17),
('v19', 'p5', 'Physiotherapy assessment', 'body', 'consult', 45, 90000, 30000, 'Clinical assessment and treatment plan by a registered physiotherapist.', 18),
('v20', 'p5', 'Post-natal core rehabilitation', 'body', 'treatment', 45, 120000, 30000, 'For clients cleared at assessment. Structured core and pelvic-floor focused exercise.', 19),
('v21', 'p5', 'Private reformer Pilates', 'body', 'beauty', 55, 180000, 40000, '1:1 reformer session — a fitness service, not therapy.', 20),
('v22', 'p5', 'Sports & recovery massage', 'body', 'beauty', 60, 160000, 30000, 'Deep-tissue recovery massage.', 21),
('v23', 'p6', 'Gel manicure', 'nails', 'beauty', 60, 110000, 20000, 'Shape, cuticle care and long-wear gel.', 22),
('v24', 'p6', 'Gel pedicure', 'nails', 'beauty', 75, 140000, 30000, 'Soak, exfoliation and gel finish.', 23),
('v25', 'p6', 'Lash lift & tint', 'nails', 'beauty', 60, 250000, 50000, 'Patch test required 48 hours before first lash service.', 24),
('v26', 'p6', 'Brow lamination & shape', 'nails', 'beauty', 45, 180000, 40000, 'Lamination, tint and tidy.', 25),
('v27', 'p7', 'Smile design consultation', 'dental', 'consult', 30, 50000, 20000, 'Examination, digital smile preview and options.', 26),
('v28', 'p7', 'Professional whitening (after exam)', 'dental', 'treatment', 60, 800000, 200000, 'In-clinic whitening for patients examined within the last 3 months.', 27),
('v29', 'p7', 'Scaling & polishing', 'dental', 'consult', 45, 150000, 30000, 'Dental clean with a brief examination.', 28),
('v30', 'p8', 'Precision haircut', 'groom', 'beauty', 45, 60000, 0, 'Cut, wash and style.', 29),
('v31', 'p8', 'Beard sculpt & hot towel', 'groom', 'beauty', 30, 40000, 0, 'Shape, line-up and hot towel.', 30),
('v32', 'p8', 'De-tan facial', 'skin', 'beauty', 45, 120000, 20000, 'Non-medical cleansing facial.', 31);
