INSERT INTO reviews (provider_id, staff_id, author, rating, service_name, body, created_on) VALUES
('p1', 's1', 'Aparna S.', 5, 'Acne & scar assessment', 'Dr. Meera explained everything without any pressure to book treatments. Left with a simple routine and a follow-up date.', '2026-10-11'),
('p1', 's3', 'Divya M.', 5, 'Hydrating deep-cleanse facial', 'Beautiful, quiet rooms. Riya was gentle and talked me through each step.', '2026-10-02'),
('p1', 's2', 'Nikhil R.', 4, 'Laser hair reduction — consult & patch test', 'Thorough patch test and honest about how many sessions might be needed. Waited 10 minutes past my time.', '2026-09-20'),
('p1', 's1', 'Sreelakshmi P.', 5, 'Dermatology consultation', 'Felt listened to. Clear written plan.', '2026-09-03'),
('p2', 's5', 'Gayathri V.', 5, 'Abhyanga full-body oil massage', 'The tharavad setting is lovely. Came out completely relaxed.', '2026-10-14'),
('p2', 's6', 'Mariam A.', 5, 'Shirodhara', 'Booked a female therapist easily. Very calm and professional.', '2026-09-28'),
('p2', 's4', 'Rohan K.', 4, 'Ayurveda physician consultation', 'Useful consultation; the doctor asked about my other medicines before suggesting anything.', '2026-09-09'),
('p3', 's7', 'Anjali N.', 5, 'Signature cut & blow-dry', 'Neha is a magician with a bob. Best cut I’ve had in Trivandrum.', '2026-10-18'),
('p3', 's8', 'Teresa J.', 5, 'Bridal makeup trial', 'The trial made the wedding morning stress-free. Looked like me, only better.', '2026-10-05'),
('p3', 's9', 'Hiba F.', 4, 'Gold radiance facial', 'Relaxing facial, a little rushed at the end.', '2026-09-15'),
('p4', 's10', 'Vishnu P.', 5, 'Hair loss consultation', 'Ordered tests before suggesting anything. Appreciated the evening slot after work.', '2026-10-09'),
('p4', 's10', 'Keerthana R.', 5, 'Skin follow-up consultation', 'Quick, clear and kind.', '2026-09-21'),
('p5', 's11', 'Ashwin T.', 5, 'Physiotherapy assessment', 'Proper assessment and a home plan I can actually follow.', '2026-10-16'),
('p5', 's12', 'Neethu L.', 5, 'Private reformer Pilates', 'Ann Maria is encouraging and precise. Great for desk-job posture.', '2026-10-01'),
('p6', 's13', 'Riya D.', 5, 'Gel manicure', 'Lasted three weeks without chipping. Spotless studio.', '2026-10-19'),
('p6', 's14', 'Sneha K.', 4, 'Lash lift & tint', 'Lovely result; remember the patch test 48 hours before.', '2026-10-07'),
('p7', 's15', 'Arun G.', 5, 'Smile design consultation', 'Showed a digital preview and told me whitening wasn’t the right first step. Honest.', '2026-10-12'),
('p7', 's15', 'Lekha S.', 4, 'Scaling & polishing', 'Gentle and on time.', '2026-09-17'),
('p8', 's16', 'Abhijith M.', 5, 'Precision haircut', 'Clean fade, no wait.', '2026-10-20'),
('p8', 's17', 'Sanjay V.', 4, 'De-tan facial', 'Good value for the price.', '2026-10-03');
